// validation.t27 -- Validation Rules and Invariants
// TDD and language policy validation for t27 specs
// phi^2 + 1/phi^2 = 3 | TRINITY

module validation_rules {
    // =====================================================================
    // Validation Result Structure
    // =====================================================================

    pub const ValidationResult = struct {
        valid: bool,
        error: []const u8,
        hint: []const u8,
    };

    // =====================================================================
    // Validation Rules
    // =====================================================================

    // Rule: TDD-Inside-Spec - Specs must have tests or invariants
    pub fn validate_tdd_contract(spec: Spec) ValidationResult {
        const has_test = spec.test_blocks.len > 0;
        const has_invariant = spec.invariant_blocks.len > 0;

        if (!has_test and !has_invariant) {
            return ValidationResult{
                .valid = false,
                .error = "TDD contract violated: spec must contain at least one 'test' or 'invariant' block",
                .hint = "See: docs/TDD-CONTRACT.md",
            };
        }

        if (has_test) {
            // Check test blocks are not empty
            for (spec.test_blocks) |test_block| {
                if (test_block.statements.len == 0) {
                    return ValidationResult{
                        .valid = false,
                        .error = "Empty test block found",
                        .hint = "Test blocks must contain test cases",
                    };
                }
            }
        }

        if (has_invariant) {
            // Check invariants have assertions
            for (spec.invariant_blocks) |inv_block| {
                if (inv_block.statements.len == 0) {
                    return ValidationResult{
                        .valid = false,
                        .error = "Empty invariant block found",
                        .hint = "Invariant blocks must contain assertions",
                    };
                }
            }
        }

        return ValidationResult{ .valid = true, .error = "", .hint = "" };
    }

    // Rule: Language Policy - Source files must be ASCII-only
    pub fn validate_language_policy(spec: Spec) ValidationResult {
        // Check if path is docs/ (Cyrillic allowed in docs)
        if (is_docs_path(spec.path)) {
            return ValidationResult{ .valid = true, .error = "", .hint = "" };
        }

        // Check for Cyrillic characters (U+0400-U+04FF)
        if (contains_cyrillic(spec.content)) {
            return ValidationResult{
                .valid = false,
                .error = "Language policy violated: source file contains Cyrillic characters",
                .hint = "Source files must be ASCII-only. See: ADR-004-language-policy.md",
            };
        }

        return ValidationResult{ .valid = true, .error = "", .hint = "" };
    }

    // Rule: De-Zig Strict - Zig files must have generated header
    pub fn validate_generated_header(zig_file_path: []const u8, zig_content: []const u8) ValidationResult {
        var lines = std.mem.splitScalar(u8, zig_content, '\n');

        if (lines.len < 4) {
            return ValidationResult{
                .valid = false,
                .error = "Zig file is too short (missing generated header)",
                .hint = "Zig files must have generated header. See: docs/GENERATED-HEADER-POLICY.md",
            };
        }

        // Check header pattern
        if (!std.mem.indexOf(u8, lines[0], "This file is generated from") != null) {
            return ValidationResult{
                .valid = false,
                .error = "Zig file lacks generated header",
                .hint = "Write .t27 spec first, then run 'tri gen'",
            };
        }

        if (!std.mem.indexOf(u8, lines[1], "DO NOT EDIT") != null) {
            return ValidationResult{
                .valid = false,
                .error = "Zig file header missing 'DO NOT EDIT' warning",
                .hint = "Generated files must not be edited",
            };
        }

        return ValidationResult{ .valid = true, .error = "", .hint = "" };
    }

    // Rule: Spec structure validation
    pub fn validate_spec_structure(spec: Spec) ValidationResult {
        // Check spec has name/title
        if (spec.name.len == 0) {
            return ValidationResult{
                .valid = false,
                .error = "Spec has no name/title",
                .hint = "Add spec name as comment at top of file",
            };
        }

        // Check spec has at least one .code or .data or .const section
        const has_code = spec.code_blocks.len > 0;
        const has_data = spec.data_blocks.len > 0;
        const has_const = spec.const_blocks.len > 0;

        // This is OK for pure test specs, but warn
        _ = has_code;
        _ = has_data;
        _ = has_const;

        return ValidationResult{ .valid = true, .error = "", .hint = "" };
    }

    // Rule: Git push validation - sealed skill required
    pub fn validate_push_skill(skill: Skill) ValidationResult {
        if (!std.mem.eql(u8, skill.status, "sealed")) {
            return ValidationResult{
                .valid = false,
                .error = "Cannot push: skill not sealed",
                .hint = "Run 'tri skill seal' first",
            };
        }

        // Check verdict
        if (std.mem.eql(u8, skill.verdict, "TOXIC")) {
            return ValidationResult{
                .valid = false,
                .error = "Cannot push: skill has toxic verdict",
                .hint = "Fix issues or supersede with new skill",
            };
        }

        return ValidationResult{ .valid = true, .error = "", .hint = "" };
    }

    // Rule: Git commit validation - active or sealed skill required
    pub fn validate_commit_skill(skill: Skill) ValidationResult {
        if (!std.mem.eql(u8, skill.status, "active") and !std.mem.eql(u8, skill.status, "sealed")) {
            return ValidationResult{
                .valid = false,
                .error = "Cannot commit: no active or sealed skill",
                .hint = "Run 'tri skill begin --issue N' first",
            };
        }

        // Check issue binding
        if (skill.issue.len == 0) {
            return ValidationResult{
                .valid = false,
                .error = "Cannot commit: skill has no bound issue",
                .hint = "Run 'tri skill begin --issue N' to bind issue",
            };
        }

        return ValidationResult{ .valid = true, .error = "", .hint = "" };
    }

    // Rule: Policy Matrix - artifact requirements by skill kind
    pub fn validate_policy_matrix(skill: Skill) ValidationResult {
        const kind = skill.kind;
        const artifacts = skill.artifacts;

        if (std.mem.eql(u8, kind, "recovery")) {
            const checkpoints = count_checkpoints(artifacts);
            const has_spec = contains_substring(artifacts, "spec");
            const has_docs = contains_substring(artifacts, "docs");

            if (checkpoints < 3 or !has_spec or !has_docs) {
                return ValidationResult{
                    .valid = false,
                    .error = "Policy gate failed for recovery skill",
                    .hint = "Recovery skills require: >=3 checkpoints, spec, docs",
                };
            }
        } else if (std.mem.eql(u8, kind, "hotfix")) {
            const checkpoints = count_checkpoints(artifacts);

            if (checkpoints < 1) {
                return ValidationResult{
                    .valid = false,
                    .error = "Policy gate failed for hotfix skill",
                    .hint = "Hotfix skills require: >=1 checkpoint",
                };
            }
        } else if (std.mem.eql(u8, kind, "feature") or std.mem.eql(u8, kind, "bugfix")) {
            // Feature and bugfix require spec with tests
            const has_spec = contains_substring(artifacts, "spec");

            if (!has_spec) {
                return ValidationResult{
                    .valid = false,
                    .error = "Policy gate failed: spec required",
                    .hint = kind ++ " skills require spec changes",
                };
            }
        }

        return ValidationResult{ .valid = true, .error = "", .hint = "" };
    }

    // Rule: Strict mode - remote URL validation
    pub fn validate_remote_url(remote_url: []const u8) ValidationResult {
        if (std.mem.indexOf(u8, remote_url, "github.com/gHashTag/t27") == null) {
            return ValidationResult{
                .valid = false,
                .error = "Forbidden remote URL",
                .hint = "Strict mode requires github.com/gHashTag/t27",
            };
        }

        return ValidationResult{ .valid = true, .error = "", .hint = "" };
    }

    // =====================================================================
    // Helper functions
    // =====================================================================

    // Check for Cyrillic characters (U+0400-U+04FF)
    pub fn contains_cyrillic(text: []const u8) bool {
        var i: usize = 0;
        while (i < text.len) : (i += 1) {
            const c = text[i];
            // UTF-8 check for Cyrillic range (simplified)
            if (c == 0xD0) {
                if (i + 1 < text.len) {
                    const next_c = text[i + 1];
                    // Cyrillic block: U+0400-U+04FF
                    if (next_c >= 0x80 and next_c <= 0xBF) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    // Check if path is in docs/ directory
    pub fn is_docs_path(path: []const u8) bool {
        return std.mem.startsWith(u8, path, "docs/") or
               std.mem.eql(u8, path, "README.md");
    }

    // Count checkpoint occurrences in artifacts string
    pub fn count_checkpoints(artifacts: []const u8) i32 {
        var count: i32 = 0;
        var i: usize = 0;
        const checkpoint_str = "checkpoint";

        while (i < artifacts.len) : (i += 1) {
            if (std.mem.startsWith(u8, artifacts[i..], checkpoint_str)) {
                count += 1;
            }
        }
        return count;
    }

    // Check if artifacts contains substring
    pub fn contains_substring(artifacts: []const u8, substr: []const u8) bool {
        return std.mem.indexOf(u8, artifacts, substr) != null;
    }
}

