// gen.t27 -- Code Generation with TDD Validation
// Commands for generating code from t27 specs with TDD enforcement

module gen_commands {
    using parser: @import("../parser/parser.t27");
    using codegen_zig: @import("../codegen/zig/codegen.t27");
    using testgen: @import("../codegen/testgen.t27");

    // =====================================================================
    // Codegen options
    // =====================================================================

    pub const GenOptions = struct {
        backend: []const u8,           // Target backend (zig, c, verilog, etc.)
        output_dir: []const u8,        // Output directory
        emit_tests: bool,              // Generate test code
        emit_conformance: bool,        // Generate conformance JSON
        optimize_level: u8,            // Optimization level
        no_prototype: bool,            // Disable prototype mode (always true - no tests allowed)
    };

    pub const CodegenOptions = struct {
        emit_comments: bool,
        emit_debug: bool,
        optimize_level: u8,
        target_triple: []const u8,
        include_runtime: bool,
    };

    pub const TestGenOptions = struct {
        backend: []const u8,
        emit_comments: bool,
        emit_benchmarks: bool,
        output_format: []const u8,
    };

    // =====================================================================
    // Command: tri gen <spec> -- Generate code from spec with TDD validation
    // =====================================================================

    pub fn gen(spec_path: []const u8, options: GenOptions) i32 {
        // Check if spec exists
        if (!file_exists(spec_path)) {
            error_print("Spec not found: ");
            error_print(spec_path);
            return 1;
        }

        // Read spec content
        const content = read_file(spec_path);
        if (content == null) {
            error_print("Failed to read spec: ");
            error_print(spec_path);
            return 1;
        }

        // Parse spec
        const context = parse(content.?, spec_path);

        if (context.has_errors()) {
            error_print("Parse errors in ");
            error_print(spec_path);
            error_print(":\n");
            for (context.errors) |err| {
                error_print("  Line ");
                print_int(err.line);
                error_print(":");
                print_int(err.column);
                error_print(": ");
                error_print(err.message);
                error_print("\n");
            }
            return 1;
        }

        // =====================================================================
        // TDD CONTRACT ENFORCEMENT (Per User Requirement: No prototype mode)
        // =====================================================================
        var has_tests = false;
        var test_count: usize = 0;
        var invariant_count: usize = 0;

        // Count tests and invariants
        if (context.ast_root.test_section) |section| {
            test_count += section.test_cases.len;
        }

        if (context.ast_root.invariant_section) |section| {
            invariant_count += section.invariants.len;
        }

        if (context.ast_root.spec_decl) |spec| {
            test_count += spec.test_blocks.len;
            invariant_count += spec.invariants.len;
        }

        has_tests = (test_count > 0) or (invariant_count > 0);

        if (!has_tests) {
            error_print("TDD contract violated: no tests in spec\n");
            error_print("\n");
            error_print("The t27 project follows Test-Driven Development where:\n");
            error_print("  1. Every spec MUST have at least one 'test' or 'invariant' block\n");
            error_print("  2. Tests are written BEFORE or WITH the implementation\n");
            error_print("  3. Conformance JSON is generated FROM tests, not hand-written\n");
            error_print("\n");
            error_print("To fix this error:\n");
            error_print("  1. Add a .test section with test cases to your spec\n");
            error_print("  2. Or add a .invariant section with invariant declarations\n");
            error_print("  3. Or use the high-level TDD syntax with 'test' and 'invariant' blocks\n");
            error_print("\n");
            error_print("Example:\n");
            error_print("  .test\n");
            error_print("      ; my_test\n");
            error_print("      ; Verify: functionality works\n");
            error_print("      ; Expected: correct result\n");
            error_print("\n");
            error_print("  .invariant\n");
            error_print("      ; my_invariant\n");
            error_print("      ; For all valid inputs: output is valid\n");
            error_print("      ; Rationale: ensures correctness\n");
            error_print("\n");
            error_print("NOTE: There is NO --allow-no-tests flag (prototype mode is disabled per policy)");
            return 1;
        }

        print("TDD contract validated: ");
        print_int(test_count);
        error_print(" tests, ");
        print_int(invariant_count);
        error_print(" invariants\n");

        // =====================================================================
        // Generate code
        // =====================================================================

        // Determine output paths
        const output_dir = if (options.output_dir.len == 0)
            "gen/" ++ options.backend
        else
            options.output_dir;

        // Create output directory if needed
        if (!dir_exists(output_dir)) {
            const mkdir_result = mkdir(output_dir);
            if (mkdir_result != 0) {
                error_print("Failed to create output directory: ");
                error_print(output_dir);
                return mkdir_result;
            }
        }

        // Generate implementation code
        const impl_output = output_dir ++ "/" ++ basename_without_ext(spec_path) ++ "." ++ options.backend;

        var codegen_result: i32 = 0;
        if (std.mem.eql(u8, options.backend, "zig")) {
            const codegen_opts = CodegenOptions{
                .emit_comments = true,
                .emit_debug = true,
                .optimize_level = options.optimize_level,
                .target_triple = "native",
                .include_runtime = true,
            };
            const zig_code = generate_zig(content.?, spec_path, codegen_opts);
            codegen_result = write_file(impl_output, zig_code);
        } else {
            error_print("Unsupported backend: ");
            error_print(options.backend);
            return 1;
        }

        if (codegen_result != 0) {
            error_print("Failed to write implementation code");
            return codegen_result;
        }

        print("Generated implementation: ");
        print(impl_output);
        error_print("\n");

        // Generate test code if requested
        if (options.emit_tests) {
            const testgen_opts = TestGenOptions{
                .backend = options.backend,
                .emit_comments = true,
                .emit_benchmarks = true,
                .output_format = "code",
            };

            const testgen = TestGen.new(context.ast_root, testgen_opts);
            const test_code = testgen.generate();

            const test_output = output_dir ++ "/" ++ basename_without_ext(spec_path) ++ "_test." ++ options.backend;
            const test_result = write_file(test_output, test_code);

            if (test_result != 0) {
                error_print("Failed to write test code");
                return test_result;
            }

            print("Generated tests: ");
            print(test_output);
            error_print("\n");
        }

        // Generate conformance JSON if requested
        var conf_output: []const u8 = "";
        if (options.emit_conformance) {
            const testgen_opts = TestGenOptions{
                .backend = "json",
                .emit_comments = true,
                .emit_benchmarks = true,
                .output_format = "json",
            };

            const testgen = TestGen.new(context.ast_root, testgen_opts);
            const conformance_json = testgen.generate();

            // Create conformance directory if needed
            const conf_dir = "conformance";
            if (!dir_exists(conf_dir)) {
                _ = mkdir(conf_dir);
            }

            conf_output = conf_dir ++ "/" ++ basename_without_ext(spec_path) ++ ".json";
            const conf_result = write_file(conf_output, conformance_json);

            if (conf_result != 0) {
                error_print("Failed to write conformance JSON");
                return conf_result;
            }

            print("Generated conformance: ");
            print(conf_output);
            error_print("\n");
        }

        error_print("\n");
        print("Code generation complete!\n");
        print("  Implementation: ");
        print(impl_output);
        error_print("\n");
        if (options.emit_tests) {
            print("  Tests: ");
            print(output_dir);
            print("/");
            print(basename_without_ext(spec_path));
            print("_test.");
            print(options.backend);
            error_print("\n");
        }
        if (options.emit_conformance) {
            print("  Conformance: ");
            print(conf_output);
            error_print("\n");
        }

        return 0;
    }

    // =====================================================================
    // Command: tri gen all -- Generate code for all specs in project
    // =====================================================================

    pub fn gen_all(options: GenOptions) i32 {
        const spec_files = glob("specs/**/*.t27");

        if (spec_files.len == 0) {
            print("No spec files found");
            return 0;
        }

        print("Found ");
        print_int(spec_files.len);
        error_print(" spec file(s)\n");

        var success_count: usize = 0;
        var fail_count: usize = 0;

        for (spec_files) |spec_path| {
            print("Generating: ");
            print(spec_path);
            error_print("\n");
            const result = gen(spec_path, options);

            if (result == 0) {
                success_count += 1;
            } else {
                fail_count += 1;
                error_print("  Failed: ");
                error_print(spec_path);
                error_print("\n");
            }
        }

        error_print("\n");
        print("Generation complete:\n");
        print("  Success: ");
        print_int(success_count);
        error_print("\n");
        print("  Failed: ");
        print_int(fail_count);
        error_print("\n");

        return if (fail_count > 0) 1 else 0;
    }

    // =====================================================================
    // Helper functions
    // =====================================================================

    // Get basename without extension
    pub fn basename_without_ext(path: []const u8) []const u8 {
        var start = path.len - 1;

        // Find last path separator
        while (start >= 0 and path[start] != '/' and path[start] != '\\') {
            if (start == 0) break;
            start -= 1;
        }

        const filename_start = start + 1;
        var end = path.len - 1;

        // Find extension
        while (end >= filename_start and path[end] != '.') {
            if (end == 0) break;
            end -= 1;
        }

        if (end == filename_start - 1) {
            return path[filename_start..];
        }

        return path[filename_start..end];
    }

