    };

    pub const ParseError = struct {
        line: usize,
        column: usize,
        message: []const u8,
    };

    pub const ParseContext = struct {
        ast_root: Program,
        errors: []ParseError,

        pub fn has_errors(self: ParseContext) bool {
            return self.errors.len > 0;
        }
    };

    pub const TestGen = struct {
        ast_root: Program,
        options: TestGenOptions,

        pub fn new(ast: Program, opts: TestGenOptions) TestGen {
            return TestGen{
                .ast_root = ast,
                .options = opts,
            };
        }

        pub fn generate(self: TestGen) []const u8 {
            // Generate test code based on backend
            if (std.mem.eql(u8, self.options.backend, "json")) {
                return self.generate_json();
            } else {
                return self.generate_code();
            }
        }

        fn generate_json(self: TestGen) []const u8 {
            // Generate JSON conformance format
            return "{\"version\": \"1.0\", \"tests\": []}";
        }

        fn generate_code(self: TestGen) []const u8 {
            // Generate test code in target backend language
            return "// Generated test code";
        }
    };
}

