// SPDX-License-Identifier: Apache-2.0
; gf64.t27 — GoldenFloat64 Encode/Decode
; GF64: 64-bit floating point with 1 sign + 18 exponent + 45 mantissa
; Bit layout: [S(1) E(18) M(45)] = [63:63][62:45][44:0]
; φ² + 1/φ² = 3 | TRINITY

module triformat-gf64;

// ============================================================================
// Constants
// ============================================================================

pub const SIGN_SHIFT : u8 = 63;
pub const EXP_SHIFT : u8 = 45;
pub const MANT_SHIFT : u8 = 0;

pub const SIGN_MASK : u64 = 0x8000000000000000;  // 1 << 63
pub const EXP_MASK : u64 = 0x7FFF800000000000;   // 0b111111111111111111 << 45
pub const MANT_MASK : u64 = 0x00007FFFFFFFFFFF; // 0b111111111111111111111111111111111111111111111

pub const EXP_MAX : u16 = 0x3FFFF;      // 262143 (all ones in 18 bits)
pub const EXP_MIN : u16 = 0x0000;

pub const BIAS : i16 = 131071;          // Exponent bias for GF64: 2^(18-1) - 1
pub const SPECIAL_EXP : u16 = 0x3FFFF;  // All ones = special (Inf/NaN)

pub const MANT_DIVISOR : u64 = 35184372088832;  // 2^45
pub const MANT_DIVISOR_SHIFT : u8 = 45;

pub const PHI_BIAS : u32 = 245760;      // Phi-optimized rounding bias

// GF64 special values
pub const GF64_ZERO_POS : u64 = 0x0000000000000000;
pub const GF64_ZERO_NEG : u64 = 0x8000000000000000;
pub const GF64_INF_POS : u64 = 0x7FFF800000000000;
pub const GF64_INF_NEG : u64 = 0xFFFF800000000000;
pub const GF64_NAN : u64 = 0xFFFF800000000001; // Sign + all exp + mantissa != 0

// ============================================================================
// Types
// ============================================================================

pub const GF64 = u64;

// ============================================================================
// Functions
// ============================================================================

// gf64_extract_sign(gf64: GF64) -> i8
// Extract sign bit (bit 63)
// Returns: 0 for positive, -1 for negative
pub fn gf64_extract_sign(gf64: GF64) i8 {
    const bit = (gf64 >> SIGN_SHIFT) & 1;
    return if (bit != 0) -1 else 0;
}

// gf64_extract_exponent(gf64: GF64) -> i16
// Extract exponent bits (bits 62-45)
// Returns: 0-262143
pub fn gf64_extract_exponent(gf64: GF64) i16 {
    return @as(i16, @intCast((gf64 >> EXP_SHIFT) & (EXP_MAX)));
}

// gf64_extract_mantissa(gf64: GF64) -> u64
// Extract mantissa bits (bits 44-0)
// Returns: 0-2^45-1
pub fn gf64_extract_mantissa(gf64: GF64) u64 {
    return gf64 & MANT_MASK;
}

// gf64_from_components(sign: i8, exp: i16, mant: u64) -> GF64
// Assemble GF64 from sign, exponent, mantissa
pub fn gf64_from_components(sign: i8, exp: i16, mant: u64) GF64 {
    const sign_bit = if (sign < 0) 1 else 0;
    return (@as(GF64, @intCast(sign_bit)) << SIGN_SHIFT) |
           (@as(GF64, @intCast(exp & EXP_MAX)) << EXP_SHIFT) |
           (mant & MANT_MASK);
}

// gf64_is_zero(gf64: GF64) -> bool
// Check if GF64 is zero (positive or negative)
pub fn gf64_is_zero(gf64: GF64) bool {
    return gf64 == GF64_ZERO_POS or gf64 == GF64_ZERO_NEG;
}

// gf64_is_special(gf64: GF64) -> bool
// Check if GF64 is Inf or NaN (exp == 262143)
pub fn gf64_is_special(gf64: GF64) bool {
    return gf64_extract_exponent(gf64) == @as(i16, @intCast(EXP_MAX));
}

// gf64_is_inf(gf64: GF64) -> bool
// Check if GF64 is infinity (exp == max, mant == 0)
pub fn gf64_is_inf(gf64: GF64) bool {
    const exp = gf64_extract_exponent(gf64);
    const mant = gf64_extract_mantissa(gf64);
    return exp == @as(i16, @intCast(EXP_MAX)) and mant == 0;
}

// gf64_is_nan(gf64: GF64) -> bool
// Check if GF64 is NaN (exp == max, mant != 0)
pub fn gf64_is_nan(gf64: GF64) bool {
    const exp = gf64_extract_exponent(gf64);
    const mant = gf64_extract_mantissa(gf64);
    return exp == @as(i16, @intCast(EXP_MAX)) and mant != 0;
}

// gf64_encode_f64(f64: f64) -> GF64
// Encode IEEE 754 double precision to GF64
// Round-to-nearest, ties to even
pub fn gf64_encode_f64(value: f64) GF64 {
    // Handle zero
    if (value == 0.0) {
        return if (std.math.signbit(value)) GF64_ZERO_NEG else GF64_ZERO_POS;
    }

    // Handle NaN
    if (std.math.isNan(value)) {
        return GF64_NAN;
    }

    // Handle Infinity
    if (std.math.isInf(value)) {
        return if (value < 0.0) GF64_INF_NEG else GF64_INF_POS;
    }

    // Extract sign
    const sign = if (value < 0.0) -1 else 0;
    const abs_value = if (value < 0.0) -value else value;

    // Get f64 components
    const f64_bits: u64 = @bitCast(abs_value);
    var f64_exp: i16 = @intCast((f64_bits >> 52) & 0x7FF) - 1023;
    var f64_mant: u64 = f64_bits & 0x000FFFFFFFFFFFFF;

    // Convert exp from f64 bias (1023) to GF64 bias (131071)
    var gf64_exp = f64_exp + BIAS;

    // Clamp exponent
    if (gf64_exp < 0) {
        // Underflow - could return subnormal, but flushing to zero for simplicity
        return if (sign < 0) GF64_ZERO_NEG else GF64_ZERO_POS;
    } else if (gf64_exp > @as(i16, @intCast(EXP_MAX - 1))) {
        return if (sign < 0) GF64_INF_NEG else GF64_INF_POS;
    }

    // Extract mantissa and scale to 45 bits
    // f64 mantissa is 52 bits, GF64 needs 45 bits
    // Shift right by 7 bits (52 - 45 = 7)
    var mant = f64_mant >> 7;

    // Round-to-nearest with ties to even
    const discarded = f64_mant & 0x7F;
    if ((discarded & 0x40) != 0) {
        // Round up
        if ((discarded & 0x3F) != 0 or (mant & 1) != 0) {
            mant += 1;
            if (mant > MANT_MASK) {
                mant = 0;
                if (gf64_exp < @as(i16, @intCast(EXP_MAX - 1))) {
                    gf64_exp += 1;
                }
            }
        }
    }

    return gf64_from_components(sign, gf64_exp, mant);
}

// gf64_decode_f64(gf64: GF64) -> f64
// Decode GF64 to IEEE 754 double precision
pub fn gf64_decode_f64(gf64: GF64) f64 {
    // Handle zero
    if (gf64_is_zero(gf64)) {
        return if (gf64_extract_sign(gf64) < 0) -0.0 else 0.0;
    }

    // Handle NaN
    if (gf64_is_nan(gf64)) {
        return std.math.nan(f64);
    }

    // Handle Infinity
    if (gf64_is_inf(gf64)) {
        return if (gf64_extract_sign(gf64) < 0) -std.math.inf(f64) else std.math.inf(f64);
    }

    // Extract components
    const sign = gf64_extract_sign(gf64);
    const exp = gf64_extract_exponent(gf64);
    const mant = gf64_extract_mantissa(gf64);

    // Decode value: mantissa * 2^(exp - bias)
    const bias_adjusted = @as(i64, exp) - @as(i64, BIAS);
    const mant_f64 = @as(f64, @floatFromInt(mant)) / @as(f64, @floatFromInt(MANT_DIVISOR));
    const value = mant_f64 * std.math.pow(f64, 2.0, @as(f64, @floatFromInt(bias_adjusted)));

    return if (sign < 0) -value else value;
}

// gf64_add(a: GF64, b: GF64) -> GF64
// Add two GF64 values
pub fn gf64_add(a: GF64, b: GF64) GF64 {
    const fa = gf64_decode_f64(a);
    const fb = gf64_decode_f64(b);
    return gf64_encode_f64(fa + fb);
}

// gf64_sub(a: GF64, b: GF64) -> GF64
// Subtract two GF64 values
pub fn gf64_sub(a: GF64, b: GF64) GF64 {
    const fa = gf64_decode_f64(a);
    const fb = gf64_decode_f64(b);
    return gf64_encode_f64(fa - fb);
}

// gf64_mul(a: GF64, b: GF64) -> GF64
// Multiply two GF64 values
pub fn gf64_mul(a: GF64, b: GF64) GF64 {
    const fa = gf64_decode_f64(a);
    const fb = gf64_decode_f64(b);
    return gf64_encode_f64(fa * fb);
}

// gf64_div(a: GF64, b: GF64) -> GF64
// Divide two GF64 values
pub fn gf64_div(a: GF64, b: GF64) GF64 {
    const fb = gf64_decode_f64(b);
    if (fb == 0.0) {
        const fa = gf64_decode_f64(a);
        return if (fa < 0.0) GF64_INF_NEG else GF64_INF_POS;
    }
    const fa = gf64_decode_f64(a);
    return gf64_encode_f64(fa / fb);
}

// gf64_abs(gf64: GF64) -> GF64
// Absolute value of GF64
pub fn gf64_abs(gf64: GF64) GF64 {
    return gf64 & ~SIGN_MASK;
}

// gf64_neg(gf64: GF64) -> GF64
// Negate GF64
pub fn gf64_neg(gf64: GF64) GF64 {
    return gf64 ^ SIGN_MASK;
}

// gf64_is_equal(a: GF64, b: GF64) -> bool
// Check if two GF64 values are equal
pub fn gf64_is_equal(a: GF64, b: GF64) bool {
    // Handle NaN: NaN != NaN
    if (gf64_is_nan(a) or gf64_is_nan(b)) {
        return false;
    }
    // Handle zero: +0 == -0
    if (gf64_is_zero(a) and gf64_is_zero(b)) {
        return true;
    }
    return a == b;
}

// gf64_is_greater(a: GF64, b: GF64) -> bool
// Check if a > b
pub fn gf64_is_greater(a: GF64, b: GF64) bool {
    if (gf64_is_nan(a) or gf64_is_nan(b)) {
        return false;
    }
    // Extract signs for comparison
    const sign_a = gf64_extract_sign(a);
    const sign_b = gf64_extract_sign(b);
    if (sign_a != sign_b) {
        return sign_a > sign_b;  // negative < positive
    }
    // Same sign: compare as unsigned (positive case) or reversed (negative case)
    if (sign_a < 0) {
        return (gf64_neg(a) > gf64_neg(b));
    }
    return a > b;
}

// gf64_max(a: GF64, b: GF64) -> GF64
// Return the larger of two GF64 values
pub fn gf64_max(a: GF64, b: GF64) GF64 {
    return if (gf64_is_greater(a, b)) a else b;
}

// gf64_min(a: GF64, b: GF64) -> GF64
// Return the smaller of two GF64 values
pub fn gf64_min(a: GF64, b: GF64) GF64 {
    return if (gf64_is_greater(a, b)) b else a;
}

// gf64_clamp(value: GF64, min: GF64, max: GF64) -> GF64
// Clamp value between min and max
pub fn gf64_clamp(value: GF64, min: GF64, max: GF64) GF64 {
    return gf64_min(gf64_max(value, min), max);
}

// gf64_lerp(a: GF64, b: GF64, t: GF64) -> GF64
// Linear interpolation between a and b
pub fn gf64_lerp(a: GF64, b: GF64, t: GF64) GF64 {
    const ft = gf64_decode_f64(t);
    const result = gf64_decode_f64(a) * (1.0 - ft) + gf64_decode_f64(b) * ft;
    return gf64_encode_f64(result);
}

// gf64_from_u32(value: u32) -> GF64
// Convert unsigned 32-bit integer to GF64
pub fn gf64_from_u32(value: u32) GF64 {
    return gf64_encode_f64(@as(f64, @floatFromInt(value)));
}

// gf64_to_u32(gf64: GF64) -> ?u32
// Convert GF64 to unsigned 32-bit integer
// Returns null if value is NaN, Infinity, or out of range
pub fn gf64_to_u32(gf64: GF64) ?u32 {
    if (gf64_is_nan(gf64) or gf64_is_inf(gf64)) {
        return null;
    }
    const value = gf64_decode_f64(gf64);
    if (value < 0.0 or value > @as(f64, @floatFromInt(std.math.maxInt(u32)))) {
        return null;
    }
    return @as(u32, @intFromFloat(value));
}

// gf64_from_i32(value: i32) -> GF64
// Convert signed 32-bit integer to GF64
pub fn gf64_from_i32(value: i32) GF64 {
    return gf64_encode_f64(@as(f64, @floatFromInt(value)));
}

// gf64_to_i32(gf64: GF64) -> ?i32
// Convert GF64 to signed 32-bit integer
// Returns null if value is NaN, Infinity, or out of range
pub fn gf64_to_i32(gf64: GF64) ?i32 {
    if (gf64_is_nan(gf64) or gf64_is_inf(gf64)) {
        return null;
    }
    const value = gf64_decode_f64(gf64);
    if (value < @as(f64, @floatFromInt(std.math.minInt(i32))) or
        value > @as(f64, @floatFromInt(std.math.maxInt(i32)))) {
        return null;
    }
    return @as(i32, @intFromFloat(value));
}

