invariant gf64_sign_mask_single_bit
    assert (SIGN_MASK & (SIGN_MASK - 1)) == 0

invariant gf64_exp_mask_no_sign
    assert (EXP_MASK & SIGN_MASK) == 0

invariant gf64_mant_mask_no_sign_exp
    assert (MANT_MASK & (SIGN_MASK | EXP_MASK)) == 0

invariant gf64_masks_cover_all_bits
    assert (SIGN_MASK | EXP_MASK | MANT_MASK) == 0xFFFFFFFFFFFFFFFF

invariant gf64_bias_power_of_two_minus_one
    assert BIAS + 1 == 131072  // 2^17

invariant gf64_special_exp_all_ones
    assert SPECIAL_EXP == EXP_MAX

invariant gf64_zero_pos_no_sign
    assert (GF64_ZERO_POS & SIGN_MASK) == 0

invariant gf64_zero_neg_has_sign
    assert (GF64_ZERO_NEG & SIGN_MASK) == SIGN_MASK

invariant gf64_inf_pos_max_exp
    assert (GF64_INF_POS & EXP_MASK) == EXP_MASK

invariant gf64_nan_has_mantissa
    assert (GF64_NAN & MANT_MASK) != 0

invariant gf64_abs_removes_sign
    assert gf64_abs(GF64_ZERO_NEG) == GF64_ZERO_POS

invariant gf64_neg_toggles_sign
    assert (gf64_neg(GF64_INF_POS) & SIGN_MASK) == SIGN_MASK

invariant gf64_from_u32_zero
    assert gf64_from_u32(0) == GF64_ZERO_POS

invariant gf64_from_i32_zero
    assert gf64_from_i32(0) == GF64_ZERO_POS

