// OLSR-style routing -- ultra-simplified for T27.
// Neighbor entries are u32-packed [id:8][quality:8][last_seen:16]; the
// 4-slot neighbor table travels as a [u32; 4] array parameter (read paths)
// while write paths return the UPDATED ENTRY plus a slot decision, so every
// function stays scalar-valued and lowers to all backends. (The original
// wave-era file packed four entries into one u32 with 256-bit masks and
// shifted the id by 56 bits inside a u32 -- no backend could ever have run
// it; rewritten 2026-08-08.)

module OlsrRouting {
    use base::types;

    const MAX_NEIGHBORS: u32 = 4;
    const VALID_TIMEOUT: u32 = 6000;
    const NO_NEIGHBOR: u32 = 0xFF;
    const NO_SLOT: u32 = 0xFF;

    // ---- Single neighbor entry: [id:8][quality:8][last_seen:16] ----

    fn create_neighbor(id: u32, quality: u32, last_seen: u32) -> u32 {
        return (((id & 0xFF) << 24) |
                ((quality & 0xFF) << 16) |
                (last_seen & 0xFFFF));
    }

    fn get_id(entry: u32) -> u32 {
        return ((entry >> 24) & 0xFF);
    }

    fn get_quality(entry: u32) -> u32 {
        return ((entry >> 16) & 0xFF);
    }

    fn get_last_seen(entry: u32) -> u32 {
        return (entry & 0xFFFF);
    }

    fn is_valid(entry: u32, time: u32) -> bool {
        return ((time - get_last_seen(entry)) < VALID_TIMEOUT);
    }

    // ---- 4-slot table, read paths over a [u32; 4] parameter ----

    fn get_id_at(table: [u32; 4], index: u32) -> u32 {
        return get_id(table[index as usize]);
    }

    fn find_index(table: [u32; 4], target_id: u32) -> u32 {
        if (get_id_at(table, 0) == target_id) { return 0; }
        if (get_id_at(table, 1) == target_id) { return 1; }
        if (get_id_at(table, 2) == target_id) { return 2; }
        if (get_id_at(table, 3) == target_id) { return 3; }
        return NO_SLOT;
    }

    // Write path: the caller stores updated_entry into the slot this returns
    // (NO_SLOT when the table is full and the id is unknown).
    fn slot_for_update(table: [u32; 4], id: u32) -> u32 {
        if (find_index(table, id) != NO_SLOT) {
            return find_index(table, id);
        }
        if (get_id_at(table, 0) == NO_NEIGHBOR) { return 0; }
        if (get_id_at(table, 1) == NO_NEIGHBOR) { return 1; }
        if (get_id_at(table, 2) == NO_NEIGHBOR) { return 2; }
        if (get_id_at(table, 3) == NO_NEIGHBOR) { return 3; }
        return NO_SLOT;
    }

    // ---- Neighbor selection ----

    fn best_of_two(a: u32, b: u32) -> u32 {
        if (get_quality(a) >= get_quality(b)) {
            return a;
        } else {
            return b;
        }
    }

    fn get_best_neighbor(table: [u32; 4]) -> u32 {
        return get_id(best_of_two(best_of_two(table[0], table[1]),
                                  best_of_two(table[2], table[3])));
    }

    // Zero out the entry that carries best_id so the second pass skips it.
    fn mask_if_id(entry: u32, best_id: u32) -> u32 {
        if (get_id(entry) == best_id) {
            return 0;
        } else {
            return entry;
        }
    }

    fn get_second_best(table: [u32; 4], best_id: u32) -> u32 {
        return get_id(best_of_two(
            best_of_two(mask_if_id(table[0], best_id), mask_if_id(table[1], best_id)),
            best_of_two(mask_if_id(table[2], best_id), mask_if_id(table[3], best_id))));
    }

    // Select top-2 MPRs, packed [best:8][second:8].
    fn select_mprs(table: [u32; 4]) -> u32 {
        let best: u32 = get_best_neighbor(table);
        let second: u32 = get_second_best(table, best);
        return ((best & 0xFF) << 8) | (second & 0xFF);
    }

    fn one_if_present(entry: u32) -> u32 {
        if (get_id(entry) != NO_NEIGHBOR) {
            return 1;
        } else {
            return 0;
        }
    }

    fn count_neighbors(table: [u32; 4]) -> u32 {
        return one_if_present(table[0]) + one_if_present(table[1])
             + one_if_present(table[2]) + one_if_present(table[3]);
    }

    // ---- Tests ----

    test create_neighbor_basic {
        n = create_neighbor(1, 100, 5000);
        assert(get_id(n) == 1, "id");
        assert(get_quality(n) == 100, "quality");
        assert(get_last_seen(n) == 5000, "timestamp");
    }

    test is_valid_within_timeout {
        n = create_neighbor(5, 200, 1000);
        assert(is_valid(n, 5000) == true, "within timeout");
    }

    test is_valid_timeout {
        n = create_neighbor(5, 200, 1000);
        assert(is_valid(n, 8000) == false, "timeout");
    }

    test table_reads_and_find {
        let table: [u32; 4] = [
            create_neighbor(1, 100, 1000),
            create_neighbor(2, 200, 2000),
            create_neighbor(3, 150, 3000),
            create_neighbor(4, 50, 4000)
        ];
        assert(get_id_at(table, 0) == 1, "entry 0");
        assert(get_id_at(table, 3) == 4, "entry 3");
        assert(find_index(table, 3) == 2, "find id 3");
        assert(find_index(table, 9) == NO_SLOT, "unknown id");
        assert(count_neighbors(table) == 4, "all four present");
    }

    test slot_decisions {
        let table: [u32; 4] = [
            create_neighbor(1, 100, 1000),
            create_neighbor(NO_NEIGHBOR, 0, 0),
            create_neighbor(3, 150, 3000),
            create_neighbor(4, 50, 4000)
        ];
        assert(slot_for_update(table, 3) == 2, "known id updates in place");
        assert(slot_for_update(table, 9) == 1, "unknown id takes the first empty slot");
        let full: [u32; 4] = [
            create_neighbor(1, 100, 1000),
            create_neighbor(2, 200, 2000),
            create_neighbor(3, 150, 3000),
            create_neighbor(4, 50, 4000)
        ];
        assert(slot_for_update(full, 9) == NO_SLOT, "full table admits nothing new");
    }

    test mpr_selection {
        let table: [u32; 4] = [
            create_neighbor(1, 100, 1000),
            create_neighbor(2, 200, 2000),
            create_neighbor(3, 150, 3000),
            create_neighbor(4, 50, 4000)
        ];
        assert(get_best_neighbor(table) == 2, "best by quality");
        assert(get_second_best(table, 2) == 3, "second best excludes the best");
        assert(select_mprs(table) == ((2 << 8) | 3), "mpr pack [best][second]");
    }
}

// SPDX-License-Identifier: Apache-2.0
// tri-net/specs/discovery.t27
// Partial spec-first flip of src/discovery.rs (T27-first).
// The HELLO beacon byte layout `[src:4][seq:4][ts:8][n:1][heard:n*4][mac:16]` is pure
// integer arithmetic: frame length, MAC offset and the parse-side length gates are
// lifted here as the single source of truth. The HMAC itself and socket I/O stay in
// Rust (T27 cannot express them).
// phi^2 + phi^-2 = 3 | TRINITY

module Discovery {
    use base::types;

    // [src:4][seq:4][ts:8][n:1] fixed header, then n*4 heard entries, then the MAC.
    const HDR_LEN : usize = 17;
    const HEARD_ENTRY_LEN : usize = 4;
    const MAC_LEN : usize = 16;
    // Timestamp freshness window (mirrors HELLO_FRESHNESS_MS in src/discovery.rs).
    const FRESHNESS_MS : u64 = 600000;

    // Offset of the MAC for a beacon listing n heard neighbors.
    fn mac_offset(n: usize) -> usize {
        return HDR_LEN + (n * HEARD_ENTRY_LEN);
    }

    // Total serialized beacon length for n heard neighbors (encode side).
    fn hello_len(n: usize) -> usize {
        return mac_offset(n) + MAC_LEN;
    }

    // Parse-side gate: a buffer of byte_len bytes claiming n neighbors is complete
    // iff it holds the header, all heard entries and the full MAC (Rust parse()).
    fn parse_len_ok(byte_len: usize, n: usize) -> bool {
        return byte_len >= hello_len(n);
    }

    // A beacon timestamp is fresh iff it is within FRESHNESS_MS of local now,
    // in either direction (clocks drift both ways).
    fn is_fresh(now_ms: u64, ts_ms: u64) -> bool {
        if (now_ms >= ts_ms) {
            return (now_ms - ts_ms) <= FRESHNESS_MS;
        } else {
            return (ts_ms - now_ms) <= FRESHNESS_MS;
        }
    }

    // ---- TDD (L4): mirror src/discovery.rs layout + parse gates ----
    test empty_beacon_is_33_bytes
        given l = hello_len(0)
        then l == 33

    test three_neighbors_is_45_bytes
        given l = hello_len(3)
        and   m = mac_offset(3)
        then l == 45
        and  m == 29

    test parse_accepts_exact_length
        given ok = parse_len_ok(45, 3)
        then ok == true

    test parse_rejects_truncated
        given short = parse_len_ok(44, 3)
        and   hdr   = parse_len_ok(16, 0)
        then short == false
        and  hdr == false

    test fresh_within_window_both_directions
        given past   = is_fresh(1000000, 500000)
        and   future = is_fresh(500000, 1000000)
        then past == true
        and  future == true

    test stale_beyond_window_rejected
        given stale = is_fresh(1000000, 300000)
        then stale == false

    // ---- invariants ----
    invariant header_is_17_bytes
        assert HDR_LEN == 17

    invariant mac_is_16_bytes
        assert MAC_LEN == 16
}

// Packet loss injection - simulates network errors
// Tests CRC error detection, lost ACKs, duplicates, replay

module PacketLossInjection {
    use base::types;

    // Error types
    const ERROR_NONE: u8 = 0;
    const ERROR_BIT_FLIP: u8 = 1;
    const ERROR_CRC_FAIL: u8 = 2;
    const ERROR_DUPLICATE: u8 = 3;
    const ERROR_OUT_OF_ORDER: u8 = 4;
    const ERROR_REPLAY: u8 = 5;

    // Inject bit flip (flip single bit in packet)
    fn inject_bit_flip(packet: u32, bit_pos: u8) -> u32 {
        if (bit_pos < 32) {
            return (packet ^ (1 << bit_pos));
        } else {
            return packet; // Invalid bit position
        }
    }

    // Simulate CRC calculation (simplified)
    fn calculate_crc(packet: u32) -> u16 {
        // Simple CRC: sum of bytes
        return (((((packet >> 24) & 0xFF) + 
                  ((packet >> 16) & 0xFF)) + 
                 ((packet >> 8) & 0xFF)) + 
                 (packet & 0xFF)) as u16;
    }

    // Verify CRC
    fn verify_crc(packet: u32, received_crc: u16) -> bool {
        return (calculate_crc(packet) == received_crc);
    }

    // Inject CRC error (corrupt packet such that CRC fails)
    fn inject_crc_error(packet: u32) -> u32 {
        return (packet + 1); // Simple corruption
    }

    // Duplicate packet (return same packet twice as tuple)
    fn duplicate_packet(packet: u32) -> (u32, u32) {
        return (packet, packet);
    }

    // Check if packets are duplicates
    fn is_duplicate(pkt1: u32, pkt2: u32) -> bool {
        return (pkt1 == pkt2);
    }

    // Inject out-of-order delivery (swap two packets)
    fn inject_out_of_order(pkt1: u32, pkt2: u32) -> (u32, u32) {
        return (pkt2, pkt1); // Swapped
    }

    // Replay attack detection (check sequence number)
    fn check_replay(packet: u32, last_seq: u32) -> bool {
        return (extract_sequence(packet) > last_seq);
    }

    fn extract_sequence(packet: u32) -> u32 {
        return (packet & 0xFFFF); // Low 16 bits = sequence
    }

    // ---- Tests ----

    test inject_bit_flip_flips_bit {
        pkt = 0x00000000;
        corrupted = inject_bit_flip(pkt, 5);
        assert(corrupted == 0x00000020, "bit 5 flipped");
    }

    test inject_bit_flip_multiple {
        pkt = 0xFFFFFFFF;
        corrupted = inject_bit_flip(pkt, 10);
        assert(corrupted == 0xFFFFFBFF, "bit 10 flipped");
    }

    test inject_bit_flip_invalid_pos {
        pkt = 0x12345678;
        result = inject_bit_flip(pkt, 35); // Invalid
        assert(result == pkt, "no change for invalid pos");
    }

    test calculate_crc_reproducible {
        pkt = 0x12345678;
        crc1 = calculate_crc(pkt);
        crc2 = calculate_crc(pkt);
        assert(crc1 == crc2, "reproducible");
    }

    test calculate_crc_different {
        pkt1 = 0x12345678;
        pkt2 = 0x12345679;
        crc1 = calculate_crc(pkt1);
        crc2 = calculate_crc(pkt2);
        assert(crc1 != crc2, "different for different data");
    }

    test verify_crc_valid {
        pkt = 0x01020304;
        crc = calculate_crc(pkt);
        valid = verify_crc(pkt, crc);
        assert(valid, "valid CRC");
    }

    test verify_crc_invalid {
        pkt = 0x01020304;
        crc = calculate_crc(pkt);
        corrupted = inject_crc_error(pkt);
        valid = verify_crc(corrupted, crc);
        assert(valid == false, "invalid CRC");
    }

    test duplicate_packet_creates_copy {
        pkt = 0xABCDEF00;
        (dup1, dup2) = duplicate_packet(pkt);
        assert(dup1 == pkt, "first copy");
        assert(dup2 == pkt, "second copy");
    }

    test is_duplicate_detects_same {
        pkt1 = 0x12345678;
        pkt2 = 0x12345678;
        assert(is_duplicate(pkt1, pkt2) == true, "same packet");
    }

    test is_duplicate_different {
        pkt1 = 0x12345678;
        pkt2 = 0x12345679;
        assert(is_duplicate(pkt1, pkt2) == false, "different packet");
    }

    test inject_out_of_order_swaps {
        pkt1 = 0x11111111;
        pkt2 = 0x22222222;
        (out1, out2) = inject_out_of_order(pkt1, pkt2);
        assert(out1 == pkt2, "swapped to pkt2");
        assert(out2 == pkt1, "swapped to pkt1");
    }

    test extract_sequence_low_bits {
        pkt = 0x1234ABCD;
        seq = extract_sequence(pkt);
        assert(seq == 0xABCD, "extracted low 16 bits");
    }

    test check_replay_newer {
        pkt = 0x00000005; // seq = 5
        last = 0x00000003; // last = 3
        assert(check_replay(pkt, last) == true, "newer packet");
    }

    test check_replay_older {
        pkt = 0x00000002; // seq = 2
        last = 0x00000005; // last = 5
        assert(check_replay(pkt, last) == false, "replay detected");
    }

    test check_replay_same {
        pkt = 0x00000005; // seq = 5
        last = 0x00000005; // last = 5
        assert(check_replay(pkt, last) == false, "same seq = replay");
    }
}

// Mesh node simulation - 2-4 node network scenarios
// Tests point-to-point, triangle, line topologies

module MeshNodeSim {
    use base::types;

    // Node IDs
    const NODE_1: u32 = 1;
    const NODE_2: u32 = 2;
    const NODE_3: u32 = 3;
    const NODE_4: u32 = 4;

    // Link quality (0-255)
    fn create_link_quality(from: u32, to: u32, quality: u8) -> u32 {
        return (((from & 0xFF) << 16) | ((to & 0xFF) << 8) | (quality as u32));
    }

    fn link_from(link: u32) -> u32 {
        return ((link >> 16) & 0xFF);
    }

    fn link_to(link: u32) -> u32 {
        return ((link >> 8) & 0xFF);
    }

    fn link_quality(link: u32) -> u8 {
        return (link & 0xFF) as u8;
    }

    // Check if link is good enough
    fn is_link_good(link: u32, threshold: u8) -> bool {
        return (link_quality(link) >= threshold);
    }

    // 2-node mesh (point-to-point)
    fn create_2node_mesh(quality: u8) -> (u32, u32) {
        return (create_link_quality(NODE_1, NODE_2, quality),
                create_link_quality(NODE_2, NODE_1, quality));
    }

    // 3-node mesh (triangle)
    fn create_3node_mesh(q12: u8, q23: u8, q31: u8) -> (u32, u32, u32) {
        return (create_link_quality(NODE_1, NODE_2, q12),
                create_link_quality(NODE_2, NODE_3, q23),
                create_link_quality(NODE_3, NODE_1, q31));
    }

    // 4-node mesh (line: 1-2-3-4)
    fn create_4node_line(q12: u8, q23: u8, q34: u8) -> (u32, u32, u32) {
        return (create_link_quality(NODE_1, NODE_2, q12),
                create_link_quality(NODE_2, NODE_3, q23),
                create_link_quality(NODE_3, NODE_4, q34));
    }

    // Route calculation (simple hop count)
    fn calculate_hops(from: u32, to: u32, topology: u8) -> u8 {
        if (from == to) {
            return 0;
        }

        if (topology == 2) {
            // 2-node: 1 hop if different
            if ((from == NODE_1 && to == NODE_2) || (from == NODE_2 && to == NODE_1)) {
                return 1;
            }
        } else if (topology == 3) {
            // 3-node triangle: 1 hop direct, 2 hops via
            if ((from == NODE_1 && to == NODE_2) || (from == NODE_2 && to == NODE_1) ||
                (from == NODE_2 && to == NODE_3) || (from == NODE_3 && to == NODE_2) ||
                (from == NODE_3 && to == NODE_1) || (from == NODE_1 && to == NODE_3)) {
                return 1;
            }
        } else if (topology == 4) {
            // 4-node line: 1-2-3-4
            if ((from == NODE_1 && to == NODE_2) || (from == NODE_2 && to == NODE_1) ||
                (from == NODE_2 && to == NODE_3) || (from == NODE_3 && to == NODE_2) ||
                (from == NODE_3 && to == NODE_4) || (from == NODE_4 && to == NODE_3)) {
                return 1;
            } else if ((from == NODE_1 && to == NODE_3) || (from == NODE_3 && to == NODE_1)) {
                return 2;
            } else if ((from == NODE_2 && to == NODE_4) || (from == NODE_4 && to == NODE_2)) {
                return 2;
            } else if ((from == NODE_1 && to == NODE_4) || (from == NODE_4 && to == NODE_1)) {
                return 3;
            }
        }

        return 255; // Invalid route
    }

    // ---- Tests ----

    test create_link_quality_correct {
        link = create_link_quality(NODE_1, NODE_2, 200);
        assert(link_from(link) == NODE_1, "from node");
        assert(link_to(link) == NODE_2, "to node");
        assert(link_quality(link) == 200, "quality");
    }

    test is_link_good_threshold {
        link = create_link_quality(NODE_1, NODE_2, 150);
        assert(is_link_good(link, 100) == true, "above threshold");
        assert(is_link_good(link, 200) == false, "below threshold");
    }

    test create_2node_mesh {
        (link1, link2) = create_2node_mesh(180);
        assert(link_from(link1) == NODE_1, "1→2");
        assert(link_from(link2) == NODE_2, "2→1");
        assert(link_quality(link1) == 180, "quality same");
    }

    test create_3node_mesh {
        (link1, link2, link3) = create_3node_mesh(100, 150, 200);
        assert(link_to(link1) == NODE_2, "1→2");
        assert(link_to(link2) == NODE_3, "2→3");
        assert(link_to(link3) == NODE_1, "3→1");
    }

    test create_4node_line {
        (link1, link2, link3) = create_4node_line(120, 130, 140);
        assert(link_from(link1) == NODE_1, "1→2");
        assert(link_from(link2) == NODE_2, "2→3");
        assert(link_from(link3) == NODE_3, "3→4");
    }

    test calculate_hops_same_node {
        hops = calculate_hops(NODE_1, NODE_1, 2);
        assert(hops == 0, "same node = 0 hops");
    }

    test calculate_hops_2node {
        hops = calculate_hops(NODE_1, NODE_2, 2);
        assert(hops == 1, "2-node = 1 hop");
    }

    test calculate_hops_3node_direct {
        hops = calculate_hops(NODE_1, NODE_2, 3);
        assert(hops == 1, "3-node direct = 1 hop");
    }

    test calculate_hops_4node_adjacent {
        hops = calculate_hops(NODE_1, NODE_2, 4);
        assert(hops == 1, "4-node adjacent = 1 hop");
    }

    test calculate_hops_4node_2hops {
        hops = calculate_hops(NODE_1, NODE_3, 4);
        assert(hops == 2, "4-node 1→3 = 2 hops");
    }

    test calculate_hops_4node_3hops {
        hops = calculate_hops(NODE_1, NODE_4, 4);
        assert(hops == 3, "4-node 1→4 = 3 hops");
    }

    test link_quality_threshold_check {
        (link1, _) = create_2node_mesh(50);
        assert(is_link_good(link1, 75) == false, "poor link");

        (link2, _) = create_2node_mesh(100);
        assert(is_link_good(link2, 75) == true, "good link");
    }
}

// TRI-NET DePIN slashing: the game-theoretic backstop. Rewarding honest relay work
// (tri_settle) is only half of it -- a node must also LOSE something for lying. Each
// node posts a bond; when its signed receipt does NOT match an independent
// re-verification (the settlement re-meters the same stream and recomputes the seal,
// as the 3-node relay demo does bit-exactly), the bond is forfeited (slashed) from its
// $TRI balance. Now cheating is strictly worse than not participating, so an honest
// receipt is the dominant strategy.

module TriSlash {
    use base::types;

    const MIN_BOND: u32 = 100; // minimum bond to take part in a payout round

    // A node must post at least the minimum bond to be admitted.
    fn bond_ok(bond: u32) -> bool {
        return bond >= MIN_BOND;
    }

    // Independent re-verification: does the node's claimed seal match the one the
    // settlement recomputed from the same relayed stream?
    fn receipt_matches(claimed_seal: u32, recomputed_seal: u32) -> bool {
        return claimed_seal == recomputed_seal;
    }

    // Saturating balance add (a node's balance never wraps down).
    fn balance_add(bal: u32, reward: u32) -> u32 {
        let sum: u32 = bal +% reward;
        if (sum < bal) {
            return 0xFFFFFFFF;
        } else {
            return sum;
        }
    }

    // Apply the round outcome to a node's balance:
    //  - matched (honest): balance += reward
    //  - mismatch (cheat): balance -= bond (slashed), saturating at 0
    fn settle_or_slash(balance: u32, reward: u32, bond: u32, matched: bool) -> u32 {
        if (matched) {
            return balance_add(balance, reward);
        } else {
            if (balance >= bond) {
                return balance - bond;
            } else {
                return 0;
            }
        }
    }

    // ---- Tests / invariants ----

    // An honest node with a valid bond is paid its reward.
    test honest_node_paid {
        b = settle_or_slash(1000, 713, 100, true);
        assert(b == 1713, "honest node gains its reward");
    }

    // A cheating node is slashed its bond.
    test cheat_node_slashed {
        b = settle_or_slash(1000, 713, 100, false);
        assert(b == 900, "cheat loses its bond, gets no reward");
    }

    // Cheating is strictly worse than being honest -- and worse than the pre-round
    // balance (a real disincentive, not just a missed reward).
    test cheating_is_worse {
        honest = settle_or_slash(1000, 713, 100, true);
        cheat  = settle_or_slash(1000, 713, 100, false);
        assert(cheat < honest, "cheat < honest");
        assert(cheat < 1000, "cheat loses vs doing nothing");
    }

    // Slash saturates at zero -- a balance can never go negative.
    test slash_saturates_at_zero {
        b = settle_or_slash(50, 0, 100, false); // bond > balance
        assert(b == 0, "slash floored at 0");
    }

    // Bond gate: too small a bond is rejected.
    test bond_gate {
        assert(bond_ok(100) == true, "at minimum");
        assert(bond_ok(500) == true, "above minimum");
        assert(bond_ok(50) == false, "below minimum rejected");
    }

    // The matcher: equal seals accept, unequal reject (drives the slash decision).
    test receipt_match {
        assert(receipt_matches(0x6EAC3F90, 0x6EAC3F90) == true, "equal seals match");
        assert(receipt_matches(0x6EAC3F90, 0xDEADBEEF) == false, "unequal seals mismatch");
    }
}

// Area optimization - resource sharing and bit-width optimization
// Tests optimization strategies for reducing resource utilization

module AreaOptimization {
    use base::types;

    // Optimization strategies
    const OPT_NONE: u32 = 0;
    const OPT_RESOURCE_SHARE: u32 = 1;
    const OPT_BIT_WIDTH_REDUCE: u32 = 2;
    const OPT_CONST_FOLD: u32 = 3;
    const OPT_FIFO_TO_RAM: u32 = 4;

    // Module complexity estimate
    fn estimate_complexity(func_count: u32, state_count: u32, max_width: u32) -> u32 {
        // Complexity = (func * 10) + (state * 20) + (max_width * 5)
        return ((func_count * 10) + (state_count * 20) + (max_width * 5));
    }

    // Calculate resource savings from sharing
    fn calculate_sharing_savings(original_count: u32, share_factor: u32) -> u32 {
        if (share_factor == 0) {
            return 0;
        }
        return (original_count - (original_count / share_factor));
    }

    // Bit-width reduction savings
    fn calculate_bitwidth_savings(original_width: u32, reduced_width: u32, instance_count: u32) -> u32 {
        if (original_width <= reduced_width) {
            return 0;
        }
        return (((original_width - reduced_width) * instance_count) / 8); // Convert to bytes
    }

    // Check if const folding applicable
    fn const_folding_applicable(operation_count: u32, const_operand_ratio: u32) -> bool {
        // Applicable if >30% operands are constants
        return (const_operand_ratio > 30);
    }

    // FIFO to RAM conversion check
    fn fifo_to_ram_applicable(depth: u32, width: u32) -> bool {
        // Convert if depth >= 16 and width >= 8
        return (depth >= 16) && (width >= 8);
    }

    // Resource type (LUT, FF, DSP, BRAM)
    fn create_resource_type(res_type: u32, amount: u32) -> u32 {
        return ((res_type & 0xF) << 28) | (amount & 0xFFFFFFF);
    }

    fn extract_resource_type(resource: u32) -> u32 {
        return ((resource >> 28) & 0xF);
    }

    fn extract_resource_amount(resource: u32) -> u32 {
        return (resource & 0xFFFFFFF);
    }

    // Optimization result
    fn create_optimization_result(strategy: u32, original: u32, optimized: u32) -> u32 {
        return (((strategy & 0xF) << 24) | 
                ((original & 0xFF) << 16) | 
                (optimized & 0xFF));
    }

    fn extract_strategy(result: u32) -> u32 {
        return ((result >> 24) & 0xF);
    }

    fn extract_original(result: u32) -> u32 {
        return ((result >> 16) & 0xFF);
    }

    fn extract_optimized(result: u32) -> u32 {
        return (result & 0xFF);
    }

    // Calculate savings percentage
    fn calculate_savings_percentage(original: u32, optimized: u32) -> u8 {
        if (original == 0) {
            return 0;
        }
        if (original <= optimized) {
            return 0;
        }
        return ((((original - optimized) * 100) / original) as u8);
    }

    // Check if optimization worth it (>10% savings)
    fn optimization_worthwhile(result: u32) -> bool {
        return (calculate_savings_percentage(extract_original(result), 
                                            extract_optimized(result)) > 10);
    }

    // Bit-width analysis
    fn analyze_bit_width(min_val: u32, max_val: u32) -> u8 {
        if (max_val == 0) {
            return 1;
        }

        // Find minimum bits needed
        if (max_val <= 0xFF) {
            return 8;
        } else if (max_val <= 0xFFF) {
            return 12;
        } else if (max_val <= 0xFFFF) {
            return 16;
        } else if (max_val <= 0xFFFFF) {
            return 20;
        } else {
            return 32;
        }
    }

    // ---- Tests ----

    test estimate_complexity_simple {
        // (10*10) + (5*20) + (16*5) = 100 + 100 + 80 = 280
        complexity = estimate_complexity(10, 5, 16);
        assert(complexity == 280, "simple complexity");
    }

    test estimate_complexity_high {
        // (50*10) + (20*20) + (32*5) = 500 + 400 + 160 = 1060
        complexity = estimate_complexity(50, 20, 32);
        assert(complexity == 1060, "high complexity");
    }

    test calculate_sharing_savings_half {
        savings = calculate_sharing_savings(1000, 2);
        assert(savings == 500, "50% savings");
    }

    test calculate_sharing_savings_quarter {
        savings = calculate_sharing_savings(1000, 4);
        assert(savings == 750, "75% savings");
    }

    test calculate_sharing_savings_zero_factor {
        savings = calculate_sharing_savings(1000, 0);
        assert(savings == 0, "zero factor = no savings");
    }

    test calculate_bitwidth_savings_reduces {
        savings = calculate_bitwidth_savings(32, 16, 100);
        assert(savings == 200, "200 bytes saved");
    }

    test calculate_bitwidth_savings_no_reduction {
        savings = calculate_bitwidth_savings(16, 32, 100);
        assert(savings == 0, "no reduction = no savings");
    }

    test const_folding_applicable_high_ratio {
        assert(const_folding_applicable(100, 50) == true, "50% constants");
    }

    test const_folding_applicable_low_ratio {
        assert(const_folding_applicable(100, 20) == false, "20% constants");
    }

    test fifo_to_ram_applicable_yes {
        assert(fifo_to_ram_applicable(32, 16) == true, "deep+wide");
    }

    test fifo_to_ram_applicable_shallow {
        assert(fifo_to_ram_applicable(8, 16) == false, "too shallow");
    }

    test fifo_to_ram_applicable_narrow {
        assert(fifo_to_ram_applicable(32, 4) == false, "too narrow");
    }

    test create_resource_type_correct {
        res = create_resource_type(1, 5000);
        assert(extract_resource_type(res) == 1, "type");
        assert(extract_resource_amount(res) == 5000, "amount");
    }

    test create_optimization_result_correct {
        result = create_optimization_result(2, 100, 70);
        assert(extract_strategy(result) == 2, "strategy");
        assert(extract_original(result) == 100, "original");
        assert(extract_optimized(result) == 70, "optimized");
    }

    test calculate_savings_percentage_30 {
        pct = calculate_savings_percentage(100, 70);
        assert(pct == 30, "30% savings");
    }

    test calculate_savings_percentage_zero {
        pct = calculate_savings_percentage(100, 100);
        assert(pct == 0, "0% savings");
    }

    test calculate_savings_percentage_negative {
        pct = calculate_savings_percentage(70, 100);
        assert(pct == 0, "negative = 0%");
    }

    test optimization_worthwhile_yes {
        result = create_optimization_result(1, 100, 80);
        assert(optimization_worthwhile(result) == true, "20% savings");
    }

    test optimization_worthwhile_no {
        result = create_optimization_result(1, 100, 95);
        assert(optimization_worthwhile(result) == false, "5% savings");
    }

    test analyze_bit_width_8bit {
        bits = analyze_bit_width(0, 255);
        assert(bits == 8, "8-bit range");
    }

    test analyze_bit_width_16bit {
        bits = analyze_bit_width(0, 65535);
        assert(bits == 16, "16-bit range");
    }

    test analyze_bit_width_32bit {
        bits = analyze_bit_width(0, 0xFFFFFFFF);
        assert(bits == 32, "32-bit range");
    }
}
